const metricsRoot=document.querySelector("#serp-db-retention-audit-summary"),rowsRoot=document.querySelector("#serp-db-retention-audit-rows"),emptyRoot=document.querySelector("#serp-db-retention-audit-empty"),number=new Intl.NumberFormat("ja-JP"),percent=new Intl.NumberFormat("ja-JP",{style:"percent",maximumFractionDigits:1}),escapeHtml=(value)=>String(value??"").replace(/[&<>"']/g,(character)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;", "'":"&#39;"}[character])),severityLabel={dropped_nonempty:"非空値drop",state_only_dropped:"状態のみdrop",projection_gap:"投影gap",implicit_context_only:"文脈のみ",retained:"保持"};
const fetchRows=async(view)=>{const rows=[];let cursor="";for(let page=0;page<10;page+=1){const params=new URLSearchParams({view,scope:"all",severity:"all",limit:"100"});if(cursor)params.set("cursor",cursor);const response=await fetch(`/api/v1/serp-db-retention?${params}`),payload=await response.json();if(!response.ok)throw new Error(payload.error??`SERP DB retention audit: HTTP ${response.status}`);rows.push(...(payload.data??[]));if(!payload.meta?.next_cursor)return{rows,payload};cursor=payload.meta.next_cursor}throw new Error("SERP DB retention audit pagination exceeded the safety limit")};
const render=async()=>{if(!metricsRoot||!rowsRoot||!emptyRoot)return;metricsRoot.innerHTML="<div class=\"metric\"><span>raw→DB保持</span><strong>読込中</strong><small>—</small></div>";try{const summaryResponse=await fetchRows("summary"),dropResponse=await fetchRows("drops"),summary=summaryResponse.payload.summary,scopes=new Map((summary.scope_summary??[]).map((row)=>[row.scope,row])),all=scopes.get("all")??{},connected=scopes.get("connected")??{},unconnected=scopes.get("unconnected")??{};metricsRoot.innerHTML=[["raw非空観測",all.raw_nonempty_observation_count??0,"件"],["exact保持",all.exact_retained_observation_count??0,"件"],["非空値drop",all.not_retained_nonempty_observation_count??0,"件"],["connected非空drop",connected.not_retained_nonempty_observation_count??0,"件"],["unconnected非空drop",unconnected.not_retained_nonempty_observation_count??0,"件"],["drop field",summary.dropped_nonempty_field_count??0,"field"],["unconnected保持率",unconnected.exact_retention_ratio??0,"率"]].map(([label,value,unit])=>`<div class="metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(unit==="率"?percent.format(value):number.format(value))}</strong><small>${escapeHtml(unit)}</small></div>`).join("");const rows=dropResponse.rows.slice().sort((left,right)=>right.not_retained_nonempty_observation_count-left.not_retained_nonempty_observation_count||left.scope.localeCompare(right.scope)||left.field.localeCompare(right.field,"ja-JP"));rowsRoot.innerHTML=rows.map((row)=>`<tr><td><strong>${escapeHtml(row.scope)}</strong></td><td>${escapeHtml(row.field)}</td><td>${escapeHtml(severityLabel[row.severity]??row.severity)}</td><td>${escapeHtml(number.format(row.raw_nonempty_observation_count??0))}</td><td>${escapeHtml(number.format(row.not_retained_nonempty_observation_count??0))}</td><td>${escapeHtml(number.format(row.not_retained_observation_count??0))}</td><td>${escapeHtml((row.source_tables??[]).join(", "))}</td></tr>`).join("");emptyRoot.hidden=rows.length>0;emptyRoot.innerHTML=rows.length?"":"<strong>DB保持差分はありません</strong><span>観測rawとSQLite投影の差分監査結果が空です。</span>"}catch(error){metricsRoot.innerHTML="";rowsRoot.innerHTML="";emptyRoot.hidden=false;emptyRoot.innerHTML=`<strong>raw→DB保持監査を読み込めませんでした</strong><span>${escapeHtml(error.message)}</span>`}};render();
